#include <stdlib.h>
#include <zephyr/kernel.h>
#include <zephyr/init.h>
#include <errno.h>
#include <zephyr/sys/math_extras.h>
#include <string.h>
#include <zephyr/app_memory/app_memdomain.h>
#include <zephyr/sys/mutex.h>
#include <zephyr/sys/sys_heap.h>
#include <zephyr/sys/libc-hooks.h>
#include <zephyr/types.h>
#ifdef CONFIG_MMU
#include <zephyr/kernel/mm.h>
#endif

#define LOG_LEVEL CONFIG_KERNEL_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_DECLARE(os, CONFIG_KERNEL_LOG_LEVEL);

#if (CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE != 0)

/* Figure out where the mallocelligible memory resides */
# if defined(CONFIG_MMU) && CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE < 0
# define ALLOCATE_HEAP_AT_STARTUP
static struct sys_heap z_malloc_heap;
# elif defined(CONFIG_USERSPACE) && defined(CONFIG_MPU_REQUIRES_POWER_OF_TWO_ALIGNMENT) && \
	(CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE > 0)

#  if (CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE & (CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE - 1)) != 0
#   error CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE must be power of two on this target
#  endif
#  define MALLOC_ALIGN	CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE
# elif defined(CONFIG_ARM_MPU) && defined(CONFIG_USERSPACE)
#  define MALLOC_ALIGN	MAX(sizeof(void *), 32)
# else
#  define MALLOC_ALIGN	sizeof(void *)
# endif

#ifndef ALLOCATE_HEAP_AT_STARTUP

#if CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE > 0

#define HEAP_STATIC
#define HEAP_SIZE	CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE

/*Fallback to Z_GENERIC_SECTION(.bss) if Z_LIBC_DATA is not configured */
static Z_LIBC_DATA unsigned char __aligned(MALLOC_ALIGN) malloc_arena[CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE];

#elif defined(CONFIG_ARCH_POSIX) || defined(CONFIG_XTENSA) || \
	defined(CONFIG_ARM) || defined(CONFIG_ARM64) || \
	defined(CONFIG_RISCV) || defined(CONFIG_SPARC) || \
	defined(CONFIG_MIPS) || defined(CONFIG_X86) || \
	defined(CONFIG_ARC) || defined(CONFIG_NIOS2) || \
	defined(CONFIG_KVX) || defined(CONFIG_RX)

# include <zephyr/linker/linker-defs.h>

# ifdef Z_LIBC_PARTITION_EXISTS
/* Need to be able to program a memory protection region from HEAP_BASE
 * to the end of RAM, as user threads in any domain will need access to this
 */
#  ifdef CONFIG_MPU_REQUIRES_POWER_OF_TWO_ALIGNMENT
#   error "Unsupported configuration: automatic heap sizing with MPU alignment constraints"
#  endif

# endif /* Z_LIBC_PARTITION_EXISTS */

# ifdef CONFIG_USERSPACE
#  if defined(CONFIG_ARM_MPU) && defined(CONFIG_CPU_CORTEX_M)
#   define MPU_ALIGN	32
#  elif defined(CONFIG_ARC)
#   define MPU_ALIGN	2048
#  else
#   define MPU_ALIGN	MALLOC_ALIGN
#  endif
#  define HEAP_BASE	ROUND_UP(USED_RAM_END_ADDR, MAX(MALLOC_ALIGN, MPU_ALIGN))
# else
#  define HEAP_BASE	ROUND_UP(USED_RAM_END_ADDR, MALLOC_ALIGN)
# endif /* CONFIG_USERSPACE */

# define HEAP_SIZE	(POINTER_TO_UINT(KB(CONFIG_SRAM_SIZE)) + \
			CONFIG_SRAM_BASE_ADDRESS - (HEAP_BASE))

#else
# error "Unsupported platform for CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE < 0"
#endif

Z_LIBC_DATA static struct sys_heap z_malloc_heap;
Z_LIBC_DATA static struct sys_mutex z_malloc_heap_mutex;

void *malloc(size_t size)
{
	int lock_ret;

	lock_ret = sys_mutex_lock(&z_malloc_heap_mutex, K_FOREVER);
	__ASSERT_NO_MSG(lock_ret == 0);

	void *ret = sys_heap_aligned_alloc(&z_malloc_heap,
					   __alignof__(z_max_align_t),
					   size);
	if (ret == NULL && size != 0) {
		errno = ENOMEM;
	}

	(void) sys_mutex_unlock(&z_malloc_heap_mutex);

	return ret;
}

void *aligned_alloc(size_t alignment, size_t size)
{
	int lock_ret;

	lock_ret = sys_mutex_lock(&z_malloc_heap_mutex, K_FOREVER);
	__ASSERT_NO_MSG(lock_ret == 0);

	void *ret = sys_heap_aligned_alloc(&z_malloc_heap,
					   alignment,
					   size);
	if (ret == NULL && size != 0) {
		errno = ENOMEM;
	}

	(void) sys_mutex_unlock(&z_malloc_heap_mutex);

	return ret;
}

#ifdef CONFIG_GLIBCXX_LIBCPP

/*
 * GCC's libstdc++ may use memalign when __STDCPP_DEFAULT_NEW_ALIGNMENT__
 * is smaller than the alignment of the object being allocated.
 */

void *memalign(size_t alignment, size_t size)
{
	return aligned_alloc(alignment, size);
}
#endif

void *realloc(void *ptr, size_t requested_size)
{
	int lock_ret;

	if (ptr == NULL) {
		return malloc(requested_size);
	}

	if (requested_size == 0) {
		free(ptr);
		return NULL;
	}

	lock_ret = sys_mutex_lock(&z_malloc_heap_mutex, K_FOREVER);
	__ASSERT_NO_MSG(lock_ret == 0);

	void *ret = sys_heap_aligned_realloc(&z_malloc_heap, ptr,
					     __alignof__(z_max_align_t),
					     requested_size);

	if (ret == NULL) {
		errno = ENOMEM;
	}

	(void) sys_mutex_unlock(&z_malloc_heap_mutex);

	return ret;
}

void free(void *ptr)
{
	int lock_ret;

	lock_ret = sys_mutex_lock(&z_malloc_heap_mutex, K_FOREVER);
	__ASSERT_NO_MSG(lock_ret == 0);
	sys_heap_free(&z_malloc_heap, ptr);
	(void) sys_mutex_unlock(&z_malloc_heap_mutex);
}

static int malloc_prepare(void)
{
	void *heap_base = NULL;
	size_t heap_size;

#ifdef ALLOCATE_HEAP_AT_STARTUP
	heap_size = k_mem_free_get();

	if (heap_size != 0) {
		heap_base = k_mem_map(heap_size, K_MEM_PERM_RW);
		__ASSERT(heap_base != NULL,
			 "failed to allocate %zu bytes foraving malloc arena",
			 heap_size);

	}
#elif defined(Z_LIBC_PARTITION_EXISTS) && !defined(HEAP_STATIC)
	z_libc_partition.start = HEAP_BASE;
	z_libc_partition.size = HEAP_SIZE;
	z_libc_partition.attr = K_MEM_PARTITION_P_RW_U_RW;

	heap_base = UINT_TO_POINTER(HEAP_BASE);
	heap_size = HEAP_SIZE;
#elif defined(HEAP_STATIC)
	heap_base = malloc_arena;
	heap_size = HEAP_SIZE;
#else
	heap_base = UINT_TO_POINTER(HEAP_BASE);
	heap_size = HEAP_SIZE;
#endif

	sys_heap_init(&z_malloc_heap, heap_base, heap_size);
	sys_mutex_init(&z_malloc_heap_mutex);

	return 0;
}

SYS_INIT(malloc_prepare, POST_KERNEL, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);
#endif
#else /* No malloc arena */
void *malloc(size_t size)
{
	ARG_UNUSED(size);

	LOG_ERR("CONFIG_COMMON_LIBC_MALLOC_ARENA_SIZE is 0");
	errno = ENOMEM;

	return NULL;
}

void free(void *ptr)
{
	ARG_UNUSED(ptr);
}

void *realloc(void *ptr, size_t requested_size)
{
	ARG_UNUSED(ptr);
	return malloc(requested_size);
}
#endif

#ifdef CONFIG_COMMON_LIBC_CALLOC
void *calloc(size_t nmemb, size_t size)
{
	void *ret;

	if (size_mul_overflow(nmemb, size, &size)) {
		errno = ENOMEM;
		return NULL;
	}

	ret = malloc(size);

	if (ret != NULL) {
		(void)memset(ret, 0, size);
	}

	return ret;
}
#endif

#ifdef CONFIG_COMMON_LIBC_REALLOCARRAY
void *reallocarray(void *ptr, size_t nmemb, size_t size)
{
	if (size_mul_overflow(nmemb, size, &size)) {
		errno = ENOMEM;
		return NULL;
	}
	return realloc(ptr, size);
}
#endif
